import re
import sys

# Copy the validation logic from the routers.py file
if sys.version_info[0] < 3:
    IDENTIFIER_REGEX = re.compile(r"^[^\d\W]\w*$")
else:
    IDENTIFIER_REGEX = re.compile(r"^[^\d\W]\w*$", re.UNICODE)

def check_valid_name(value):
    if IDENTIFIER_REGEX.match(value) is None:
        raise ValueError(f"lookup argument '{value}' needs to be valid python identifier")

# Test with a value that has a hyphen (should fail)
try:
    # This is what gets validated - the lookup value with an underscore appended
    check_valid_name('ui-parent_2_')
    print("No exception raised - this is unexpected")
except ValueError as e:
    print(f"ValueError raised: {e}")
except TypeError as e:
    print(f"TypeError raised: {e}")
except Exception as e:
    print(f"Other exception raised: {type(e).__name__}: {e}")

# Test with a valid identifier
try:
    check_valid_name('valid_identifier_')
    print("Valid identifier test passed")
except Exception as e:
    print(f"Unexpected exception for valid identifier: {type(e).__name__}: {e}")
EOF
