if sys.version_info[0] < 3:
    IDENTIFIER_REGEX = re.compile(r"^[^\d\W]\w*$")
else:
    IDENTIFIER_REGEX = re.compile(r"^[^\d\W]\w*$", re.UNICODE)

class NestedMixin:
    def __init__(self, lookup=None):
        self.nest_count = 1
        self.lookup = lookup or f'nested_{self.nest_count}'
        self.nest_prefix = self.lookup + '_'
        self.check_valid_name(self.nest_prefix, self.lookup)

    def check_valid_name(self, value: str, original_value: str = None) -> None:
        original_value = original_value or value
        if IDENTIFIER_REGEX.match(value) is None:
            raise ValueError(f"lookup argument '{original_value}' needs to be valid python identifier")

# Test with a valid identifier
try:
    mixin = NestedMixin('valid_lookup')
    print("SUCCESS: Valid lookup accepted")
except Exception as e:
    print(f"FAILURE: Valid lookup rejected: {type(e).__name__}: {e}")

# Test with an invalid identifier (contains hyphen)
try:
    mixin = NestedMixin('ui-parent_2')
    print("FAILURE: Invalid lookup accepted")
except ValueError as e:
    print(f"SUCCESS: ValueError raised as expected: {e}")
