    if "ui-parent_2" in str(e) and not "ui-parent_2_" in str(e):
        print("SUCCESS: Error message shows the original lookup value")
    else:
        print(f"ISSUE: Error message doesn't show the original lookup value correctly: {e}")
except TypeError as e:
    print(f"FAILURE: TypeError raised instead of ValueError: {e}")
except Exception as e:
    print(f"FAILURE: Other exception raised: {type(e).__name__}: {e}")

